oxy_webhelp_navlinks = {"tocId-d39307e9758":{"topics":[{"title":"Migration between cloud providers","shortdesc":"<p class=\"shortdesc\">When changing cloud providers for archiving, create an archival location with the         target provider and update your SLA Domain archival policies to redirect new archives while         retaining access to existing archived data.<\/p>","href":"archival\/arch_migrating_cloud_providers.html","attributes":{"data-id":"arch_migrating_cloud_providers"},"menu":{"hasChildren":false},"tocID":"arch_migrating_cloud_providers-d39307e9759","topics":[]},{"title":"Migration of archival locations to RCV","shortdesc":"<p class=\"shortdesc\">You can migrate existing archival location data from Amazon S3, S3-compatible, or         Azure Blob storage to Rubrik Cloud Vault by using a supported migration tool with assistance         from Rubrik Professional Services.<\/p>","href":"saas\/migration_arch_loc_rcv.html","attributes":{"data-id":"migration_arch_loc_rcv"},"menu":{"hasChildren":false},"tocID":"migration_arch_loc_rcv-d39307e9770","next":"migration_arch_loc_rcv-d39307e9770"}]}};